        $RU_COUNTRY = ['Russia'];

        function getUserCountryByIP($ip = null) {
            if ($ip === null) {
                if (!empty($_SERVER['HTTP_CLIENT_IP'])) {
                    $ip = $_SERVER['HTTP_CLIENT_IP'];
                } elseif (!empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
                    $ip = explode(',', $_SERVER['HTTP_X_FORWARDED_FOR'])[0];
                } else {
                    $ip = $_SERVER['REMOTE_ADDR'];
                }
            }

            $url = "http://ip-api.com/json/" . urlencode($ip) . "?fields=country";
            $response = @file_get_contents($url);

            if ($response !== false) {
                $data = json_decode($response, true);
                if (isset($data['country'])) {
                    return $data['country'];
                }
            }
            return null;
        }

    // Получение каноничной ссылки сайта Bitrix

    function getCanonicalUrl($siteId) {
        // Получить url сайта с SITE_ID = 1
        if (class_exists('CSite')) {
            $rsSites = CSite::GetByID($siteId);
            if ($arSite = $rsSites->Fetch()) {
                $serverName = $arSite['SERVER_NAME'];
                if (!$serverName) {
                    // Если SERVER_NAME не задан, пробуем взять из настроек
                    $serverName = $_SERVER['HTTP_HOST'];
                }
                return $serverName;
            }
        }
        // fallback
        $protocol = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
        $url = $protocol . '://' . $_SERVER['HTTP_HOST'] . $_SERVER['REQUEST_URI'];
        return $url;
    }

    // Пример использования:
    $userCountry = getUserCountryByIP();
    $currentDomain = $_SERVER['HTTP_HOST'];
    $targetSiteId = in_array($userCountry, $RU_COUNTRY) ? "s1" : "s2";

    if ($userCountry) {
        $currentSiteURL = getCanonicalUrl($targetSiteId);

        if ($currentDomain != $currentSiteURL) {
            // header("Location: https://" . $currentSiteURL);
        }
    }
